    --grid: #2c2c2a; --axis: #45453f; --ring: rgba(255,255,255,.12); --focus: #86b6ef;
    --k1: #3987e5; --k2: #d95926; --k3: #199e70; --k4: #c98500; --k5: #d55181; --k6: #008300; --k7: #9085e9;
    --k-other: #6d6c66; --path: #3987e5; --path-ink: #101010; --wait: #898781;
