    --good: #3cc23c; --warn: #f0b23a; --bad: #ef6b6b; --good-bg: #16301a; --warn-bg: #352a10; --bad-bg: #3a1a1a;
  }
}
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; scroll-padding-top: 52px; }
body { margin: 0; background: var(--plane); color: var(--ink); font: 13.5px/1.45 var(--sans); }
a { color: var(--focus); }
code, .mono { font-family: var(--mono); font-size: 12px; }
h1, h2, h3 { margin: 0; font-weight: 650; }
h1 { font-size: 19px; }
h2 { font-size: 15.5px; }
h3 { font-size: 13.5px; margin: 14px 0 6px; }
button, input, select { font: inherit; color: inherit; }
button { background: var(--surface); border: 1px solid var(--axis); border-radius: 5px; padding: 3px 9px; cursor: pointer; }
button:hover { background: var(--raised); }
:focus-visible { outline: 2px solid var(--focus); outline-offset: 1px; }
[hidden] { display: none !important; }
#js-errors { margin: 0; padding: 8px 16px; background: var(--bad-bg); color: var(--bad); font: 12px var(--mono); white-space: pre-wrap; }

#index { position: sticky; top: 0; z-index: 5; background: var(--surface); border-bottom: 1px solid var(--grid); }
#index .bar { display: flex; align-items: center; gap: 18px; padding: 0 16px; max-width: 1440px; margin: 0 auto; height: 44px; overflow-x: auto; white-space: nowrap; }
#index b { font-weight: 650; }
#index ol { display: flex; gap: 2px; margin: 0; padding: 0; list-style: none; }
#index a { display: block; padding: 4px 8px; border-radius: 5px; color: var(--ink-2); text-decoration: none; }
#index a:hover { background: var(--raised); color: var(--ink); }
#index a small { color: var(--muted); margin-left: 3px; font-variant-numeric: tabular-nums; }

main { max-width: 1440px; margin: 0 auto; padding: 8px 16px 48px; }
section { background: var(--surface); border: 1px solid var(--grid); border-radius: 8px; padding: 14px 16px 16px; margin-top: 12px; min-width: 0; }
.head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 14px; margin-bottom: 10px; }
.head .count { color: var(--muted); font-variant-numeric: tabular-nums; }
.head .tools { margin-left: auto; display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
.na { color: var(--ink-2); margin: 4px 0; }
.na::before { content: "–  "; color: var(--muted); }
.muted { color: var(--muted); }
.notes { margin: 6px 0 0; padding-left: 18px; color: var(--ink-2); font-size: 12.5px; }
details > summary { cursor: pointer; color: var(--ink-2); font-size: 12.5px; margin-top: 8px; }
.filter { width: 220px; max-width: 100%; padding: 3px 8px; border: 1px solid var(--axis); border-radius: 5px; background: var(--surface); }

.badge { display: inline-block; padding: 0 6px; border-radius: 4px; font-size: 11.5px; line-height: 18px; background: var(--raised); color: var(--ink-2); white-space: nowrap; vertical-align: 1px; }
.badge.good { background: var(--good-bg); color: var(--good); }
.badge.warn { background: var(--warn-bg); color: var(--warn); }
.badge.bad { background: var(--bad-bg); color: var(--bad); }
.badge.path { background: var(--path); color: var(--path-ink); }

/* header */
.title { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 12px; }
.input-path { display: block; margin-top: 3px; color: var(--ink-2); overflow-wrap: anywhere; }
.facts { display: flex; flex-wrap: wrap; gap: 4px 18px; margin: 10px 0 0; padding: 0; list-style: none; color: var(--ink-2); }
.facts li strong { color: var(--ink); font-weight: 600; }
.tiles { display: flex; flex-wrap: wrap; gap: 1px; margin: 14px 0 0; background: var(--grid); border: 1px solid var(--grid); border-radius: 6px; overflow: hidden; }
.tiles > div { flex: 1 1 150px; background: var(--surface); padding: 8px 11px; min-width: 0; }
.tiles dt { color: var(--muted); font-size: 12px; }
.tiles dd { margin: 1px 0 0; font-size: 18px; font-weight: 600; overflow-wrap: anywhere; }
.tiles dd.text { font-size: 12.5px; font-weight: 400; color: var(--ink-2); padding-top: 3px; }
.tiles small { display: block; color: var(--muted); font-size: 11.5px; }
.banner { margin-top: 12px; padding: 9px 12px; border-left: 3px solid var(--warn); background: var(--warn-bg); border-radius: 0 6px 6px 0; }
.banner ol { margin: 4px 0; padding-left: 20px; }
.banner code { overflow-wrap: anywhere; }

/* timeline */
.legend { display: flex; flex-wrap: wrap; gap: 4px 14px; margin: 0 0 8px; padding: 0; list-style: none; color: var(--ink-2); font-size: 12px; }
.legend i { display: inline-block; width: 12px; height: 10px; border-radius: 2px; margin-right: 5px; vertical-align: -1px; }
.legend i.line { height: 2px; vertical-align: 3px; }
.legend i.hatch { background-image: repeating-linear-gradient(135deg, currentColor 0 1.5px, transparent 1.5px 4px); color: var(--wait); }
.canvas-wrap { position: relative; border: 1px solid var(--grid); border-radius: 6px; overflow: hidden; background: var(--surface); }
canvas { display: block; width: 100%; touch-action: none; cursor: grab; }
canvas:active { cursor: grabbing; }
.print-img { display: none; width: 100%; }
#tip { position: fixed; z-index: 20; pointer-events: none; max-width: 360px; padding: 6px 9px; border-radius: 6px; background: var(--ink); color: var(--surface); font-size: 12px; line-height: 1.4; box-shadow: 0 2px 8px rgba(0,0,0,.25); }
#tip div:first-child { font-weight: 600; overflow-wrap: anywhere; }
.footnote { margin-top: 6px; color: var(--ink-2); font-size: 12.5px; }

/* tables */
.tscroll { overflow-x: auto; }
table { border-collapse: collapse; width: 100%; font-variant-numeric: tabular-nums; }
caption { text-align: left; color: var(--muted); font-size: 12px; padding: 0 0 4px; }
th, td { padding: 4px 8px; border-bottom: 1px solid var(--grid); text-align: left; vertical-align: top; }
th { font-weight: 600; color: var(--ink-2); font-size: 12px; white-space: nowrap; background: var(--surface); }
thead th { border-bottom: 1px solid var(--axis); }
th button { border: 0; background: none; padding: 0; font-weight: 600; color: inherit; }
th[aria-sort="ascending"] button::after { content: " ↑"; }
th[aria-sort="descending"] button::after { content: " ↓"; }
td.num, th.num { text-align: right; }
td.path { font-family: var(--mono); font-size: 12px; overflow-wrap: anywhere; min-width: 220px; }
tbody tr[data-row] { cursor: default; }
tbody tr[data-row].open-able { cursor: pointer; }
tbody tr[data-row]:hover, tbody tr[data-row]:focus { background: var(--raised); }
tbody tr.other td:first-child { font-style: italic; }
tbody tr.group th { background: var(--raised); font-family: var(--mono); font-weight: 600; color: var(--ink); overflow-wrap: anywhere; white-space: normal; }
tbody tr.group th span { font-family: var(--sans); font-weight: 400; color: var(--ink-2); margin-left: 10px; }
tbody tr.members td { background: var(--plane); font-family: var(--mono); font-size: 11.5px; }
tbody tr.members ul { margin: 0; padding-left: 18px; columns: 2 360px; }
tfoot td { color: var(--ink-2); border-bottom: 0; }
.more { margin-top: 8px; display: flex; gap: 10px; align-items: center; color: var(--muted); font-size: 12px; }
.mix { display: flex; gap: 2px; width: 140px; height: 10px; }
.mix span { display: block; height: 100%; border-radius: 2px; min-width: 1px; }
.tog { padding: 0 5px; font-size: 11.5px; margin-left: 6px; }
.topped tbody tr.beyond-top, .topped tbody tr.beyond-top + tr.members { display: none; }
.cp-grouped tbody tr.cp-member.cp-folded { display: none; }
tbody tr.cp-group td { background: var(--raised); }
tbody tr.cp-group td:first-child { font-weight: 600; }
.more button { font-weight: 600; }
a.why { font-size: 11px; margin-left: 4px; }
code .ph { color: var(--muted); font-style: italic; user-select: none; -webkit-user-select: none; }
.future { color: var(--warn); font-size: 12px; margin-left: 6px; }
.unk-notes li:target { background: var(--warn-bg); }

/* findings */
.finding { border-top: 1px solid var(--grid); padding: 10px 0; }
.finding:first-of-type { border-top: 0; }
.finding h3 { margin: 0 0 4px; display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap; }
.finding dl { display: grid; grid-template-columns: max-content 1fr; gap: 2px 12px; margin: 6px 0; font-size: 12.5px; }
.finding dt { color: var(--muted); }
.finding dd { margin: 0; }
.finding pre, .plan pre { margin: 4px 0; padding: 6px 9px; background: var(--raised); border-radius: 5px; font: 12px var(--mono); white-space: pre-wrap; overflow-wrap: anywhere; }
.finding .ev li code { overflow-wrap: anywhere; }
.plan { margin: 0 0 8px; }
.plan ol { margin: 4px 0 6px; padding-left: 22px; }
.plan li code { overflow-wrap: anywhere; }
.outcomes details ul { margin-top: 4px; }
.empty { padding: 18px 0 6px; color: var(--ink-2); }

/* drawer */
#drawer { position: fixed; top: 0; right: 0; bottom: 0; z-index: 10; width: min(620px, 100vw); background: var(--surface); border-left: 1px solid var(--axis); box-shadow: -6px 0 24px rgba(0,0,0,.18); display: flex; flex-direction: column; }
#drawer .dhead { display: flex; align-items: baseline; gap: 10px; padding: 12px 16px; border-bottom: 1px solid var(--grid); }
#drawer .dhead h2 { overflow-wrap: anywhere; }
#drawer .dhead button { margin-left: auto; }
#drawer .dbody { overflow: auto; padding: 10px 16px 24px; }

footer { max-width: 1440px; margin: 0 auto; padding: 0 16px 24px; color: var(--muted); font-size: 12px; }

/* xcblame:compare:css:start */
/* v0.4 lane B: styles of the #compare section only (every selector starts with #compare or .cmp-). */
#compare .cmp-block { margin-top: 18px; }
#compare .cmp-block:first-child { margin-top: 0; }
#compare .cmp-block > h3 { margin: 0 0 6px; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; }
#compare .cmp-block > h3 small { font-weight: 400; color: var(--muted); font-size: 12.5px; }
#compare .cmp-sides { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 12px; }
#compare .cmp-side { border: 1px solid var(--grid); border-radius: 6px; padding: 10px 12px; background: var(--plane); min-width: 0; }
#compare .cmp-side h3 { margin: 0 0 6px; display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap; }
#compare .cmp-side dl { display: grid; grid-template-columns: max-content 1fr; gap: 2px 12px; margin: 0; font-size: 12.5px; }
#compare .cmp-side dt { color: var(--muted); }
#compare .cmp-side dd { margin: 0; overflow-wrap: anywhere; font-variant-numeric: tabular-nums; }
#compare .cmp-side dd.diff { font-weight: 600; }
#compare .cmp-side dd.diff::after { content: "  differs"; font-weight: 400; color: var(--warn); font-size: 11.5px; }
#compare .cmp-headline { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 1px; background: var(--grid); border: 1px solid var(--grid); border-radius: 6px; overflow: hidden; }
#compare .cmp-headline > div { background: var(--surface); padding: 8px 11px; min-width: 0; }
#compare .cmp-headline .cmp-label { color: var(--muted); font-size: 12px; display: block; }
#compare .cmp-headline .cmp-num { font-size: 17px; font-weight: 600; display: block; font-variant-numeric: tabular-nums; }
#compare .cmp-headline small { display: block; color: var(--ink-2); font-size: 12px; font-variant-numeric: tabular-nums; }
#compare .cmp-delta.slower { color: var(--bad); }
#compare .cmp-delta.faster { color: var(--good); }
#compare #cmp-verdict { font-size: 14px; line-height: 22px; padding: 0 9px; }
#compare #cmp-band, #compare #cmp-failed { grid-column: 1 / -1; }
#compare #cmp-failed { background: var(--bad-bg); color: var(--bad); font-weight: 600; }
#compare #cmp-band small { color: var(--ink-2); }
#compare .cmp-why { margin: 0; padding-left: 20px; }
#compare .cmp-why li { margin: 2px 0; }
#compare .cmp-why .badge { margin-right: 4px; }
#compare .cmp-bars { display: grid; gap: 2px; }
#compare .cmp-bar-row { display: grid; grid-template-columns: minmax(120px, 22%) minmax(120px, 1fr) minmax(190px, 34%); gap: 10px; align-items: center; padding: 2px 0; border-bottom: 1px solid var(--grid); }
#compare .cmp-bar-row.other .cmp-key { font-style: italic; }
#compare .cmp-key { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--mono); font-size: 12px; }
#compare .cmp-val { font-variant-numeric: tabular-nums; font-size: 12px; color: var(--ink-2); white-space: nowrap; }
#compare .cmp-track { position: relative; height: 12px; background: linear-gradient(to right, transparent calc(50% - .5px), var(--axis) calc(50% - .5px), var(--axis) calc(50% + .5px), transparent calc(50% + .5px)); }
#compare .cmp-fill { position: absolute; top: 1px; bottom: 1px; min-width: 1px; border-radius: 2px; }
#compare .cmp-fill.pos { background: var(--bad); }
#compare .cmp-fill.neg { background: var(--good); }
#compare .cmp-legend { display: flex; gap: 14px; color: var(--ink-2); font-size: 12px; margin: 0 0 4px; }
#compare .cmp-legend i { display: inline-block; width: 12px; height: 9px; border-radius: 2px; margin-right: 5px; }
#compare td.cmp-pos { color: var(--bad); }
#compare td.cmp-neg { color: var(--good); }
#compare .cmp-mini { display: inline-block; height: 8px; border-radius: 2px; min-width: 1px; vertical-align: middle; margin-right: 6px; }
#compare .cmp-mini.pos { background: var(--bad); }
#compare .cmp-mini.neg { background: var(--good); }
#compare #cmp-timeline canvas { cursor: default; touch-action: auto; margin-bottom: 8px; }
#compare .cmp-axis-label { color: var(--ink-2); font-size: 12px; margin: 6px 0 2px; }
#compare .cmp-env-hit td:first-child, #compare .cmp-env-hit th { font-weight: 600; }
@media (max-width: 640px) {
  #compare .cmp-bar-row { grid-template-columns: 1fr; gap: 2px; }
  #compare .cmp-val { white-space: normal; }
}
/* xcblame:compare:css:end */
/* xcblame:trend:css:start */
/* v0.4 lane C: styles of the #trend section only (prefix every selector with #trend or .trend-). */
#trend .trend-group { margin-top: 14px; }
#trend .trend-group > h3 { margin: 0 0 8px; overflow-wrap: anywhere; }
#trend .trend-grid { display: grid; grid-template-columns: 1fr; gap: 12px; }
#trend .trend-series { margin: 0; padding: 8px 10px 6px; border: 1px solid var(--grid); border-radius: 6px; background: var(--surface); min-width: 0; }
#trend .trend-series figcaption { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 12px; margin-bottom: 4px; font-variant-numeric: tabular-nums; }
#trend .trend-p50 { color: var(--k3); font-weight: 600; }
#trend .trend-p95 { color: var(--k4); font-weight: 600; }
#trend .trend-svg { display: block; width: 100%; max-width: 640px; height: auto; }
#trend .trend-svg text { fill: var(--muted); font: 10px var(--sans); }
#trend .trend-base { stroke: var(--axis); stroke-width: 1; }
#trend .trend-line { fill: none; stroke: var(--k1); stroke-width: 1.5; stroke-linejoin: round; }
#trend .trend-rule { stroke-width: 1; stroke-dasharray: 4 3; }
#trend .trend-rule.p50 { stroke: var(--k3); }
#trend .trend-rule.p95 { stroke: var(--k4); }
#trend .trend-svg text.trend-rule-label.p50 { fill: var(--k3); }
#trend .trend-svg text.trend-rule-label.p95 { fill: var(--k4); }
#trend .trend-marker { stroke: var(--k2); stroke-width: 1.25; stroke-dasharray: 2 2; }
#trend .trend-svg text.trend-marker-label { fill: var(--k2); }
#trend .trend-point { fill: var(--k1); stroke: var(--surface); stroke-width: 1; cursor: pointer; }
#trend .trend-point.trend-nowall { fill: none; stroke: var(--k1); }
#trend .trend-point:hover, #trend .trend-point:focus { fill: var(--k2); stroke: var(--ink); outline: none; }
#trend .trend-readout { min-height: 17px; color: var(--ink-2); font: 11.5px var(--mono); overflow-wrap: anywhere; }
#trend .trend-series details > summary { margin-top: 2px; }
/* xcblame:trend:css:end */
/* xcblame:why:css:start */
#why .why-facts { margin-top: 0; }
#why .why-row-strip { display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: baseline; margin: 10px 0; }
#why #why-unknown { padding: 6px 10px; border: 1px solid var(--grid); border-radius: 6px; background: var(--surface); }
#why #why-unknown[data-share]:not([data-share="0"]) { border-color: var(--warn); }
#why #why-unknown code { font: 12px var(--mono); overflow-wrap: anywhere; }
#why #why-tabs { display: flex; gap: 4px; margin: 12px 0 6px; border-bottom: 1px solid var(--axis); }
#why #why-tabs button { border: 1px solid var(--grid); border-bottom: 0; border-radius: 5px 5px 0 0; padding: 3px 10px; background: var(--raised); color: var(--ink-2); }
#why #why-tabs button[aria-selected="true"] { background: var(--surface); color: var(--ink); font-weight: 600; }
#why .why-rank { margin: 0; padding: 0; list-style: none; }
#why .why-rank li { display: grid; grid-template-columns: 2.2em minmax(0, 1fr) 7em 10em; gap: 2px 10px; align-items: center; padding: 3px 0; border-bottom: 1px solid var(--grid); font-variant-numeric: tabular-nums; }
#why .why-rank .why-n { color: var(--muted); text-align: right; }
#why .why-rank .why-secs { text-align: right; }
#why .why-bar { height: 8px; border-radius: 2px; background: var(--k1); min-width: 1px; }
#why .why-rank li.why-unknown-row .why-bar { background: var(--warn); }
#why .why-class { margin-top: 10px; border-top: 1px solid var(--grid); padding-top: 6px; }
#why .why-class > summary { font-weight: 600; color: var(--ink); font-size: 13px; }
#why .why-cause { margin: 8px 0 8px 12px; }
#why .why-cause h4 { margin: 0 0 3px; font-size: 13px; display: flex; flex-wrap: wrap; gap: 4px 8px; align-items: baseline; }
#why .why-cause .why-ev { margin: 2px 0 4px; padding-left: 18px; color: var(--ink-2); font-size: 12px; }
#why .why-cause .why-ev li { overflow-wrap: anywhere; }
@media (max-width: 640px) { #why .why-rank li { grid-template-columns: 2em minmax(0, 1fr) 6em; } #why .why-rank .why-bar-cell { display: none; } }
/* xcblame:why:css:end */
/* xcblame:fixedcosts:css:start */
#fixedcosts .fc-assumption { margin-left: 6px; }
#fixedcosts .fc-tasks td { padding: 4px 8px 8px 24px; background: var(--raised); }
#fixedcosts .fc-tasks table { width: 100%; font-size: 12.5px; }
#fixedcosts .fc-tasks th, #fixedcosts .fc-tasks td td { text-align: left; padding: 1px 8px 1px 0; background: none; }
#fixedcosts .fc-tasks .num { text-align: right; font-variant-numeric: tabular-nums; }
#fixedcosts #fc-total { margin: 8px 0 0; color: var(--ink-2); }
/* xcblame:fixedcosts:css:end */
/* xcblame:modulegraph:css:start */
#modulegraph .mg-tools { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin: 6px 0; }
#modulegraph .mg-hint { color: var(--muted); font-size: 12px; }
#modulegraph .mg-frame { border: 1px solid var(--grid); border-radius: 6px; background: var(--plane); overflow: hidden; touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#modulegraph .mg-frame.mg-panning { cursor: grabbing; }
#modulegraph svg#mg-svg { display: block; width: 100%; }
#modulegraph .mg-node rect { fill: var(--surface); stroke: var(--axis); stroke-width: 1; }
#modulegraph .mg-node.mg-onchain rect { stroke: var(--path); stroke-width: 2; }
#modulegraph .mg-node.mg-collapsed rect { fill: var(--raised); stroke-dasharray: 4 3; }
#modulegraph .mg-node text { fill: var(--ink); font: 11.5px var(--sans); pointer-events: none; }
#modulegraph .mg-node text.mg-sub { fill: var(--muted); font-size: 10px; }
#modulegraph .mg-node { cursor: pointer; outline: none; }
#modulegraph .mg-node:focus rect, #modulegraph .mg-node:hover rect { stroke: var(--focus); stroke-width: 2; }
#modulegraph .mg-badge rect { stroke: none; }
#modulegraph .mg-variants rect { fill: var(--warn-bg); }
#modulegraph .mg-variants text { fill: var(--warn); font-size: 10px; }
#modulegraph .mg-macros rect { fill: var(--raised); }
#modulegraph .mg-macros text { fill: var(--ink-2); font-size: 10px; }
#modulegraph .mg-edge { fill: none; stroke: var(--axis); stroke-width: 1.2; }
#modulegraph .mg-edge.mg-critical { stroke: var(--path); stroke-width: 2.6; stroke-dasharray: 7 3; }
#modulegraph .mg-lists { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(260px, 100%), 1fr)); gap: 4px 18px; }
#modulegraph .mg-lists ol, #modulegraph .mg-lists ul { margin: 0; padding-left: 20px; font-variant-numeric: tabular-nums; }
#modulegraph .mg-lists .na { margin: 0; }
@media print { #modulegraph .mg-frame { overflow: visible; } #modulegraph .mg-tools { display: none; } }
/* xcblame:modulegraph:css:end */
/* clarity (2026-11-02): start here, section guides, column definitions, footnotes, glossary, charts */
.start { border-left: 4px solid var(--path); }
.start p { margin: 4px 0; max-width: 1000px; }
.start .key { font-size: 15px; }
.start ol { margin: 6px 0 2px; padding-left: 22px; max-width: 1000px; }
.start li { margin: 4px 0; }
.start li .how { display: block; color: var(--ink-2); font-size: 12.5px; }
.start li .how code { overflow-wrap: anywhere; }
.start .xcode-own { color: var(--ink-2); max-width: 1000px; }
.start .xcode-own li { margin: 2px 0; }
.start .alert, #verify-abort { border-left: 3px solid var(--bad); background: var(--bad-bg); padding: 6px 10px; border-radius: 0 6px 6px 0; max-width: 1000px; }
.housekeeping { color: var(--ink-2); }
.finding .inxcode { margin: 2px 0 4px; padding-left: 18px; }
.finding .inxcode li { overflow-wrap: anywhere; }
.plan .commit { margin: 4px 0 8px; padding: 6px 10px; border-left: 3px solid var(--warn); background: var(--warn-bg); border-radius: 0 6px 6px 0; }
.plan li .note { color: var(--muted); font-size: 12px; margin-left: 6px; }
#sum-what { margin-top: 6px; }
.what-this-shows, .what-to-do { margin: -4px 0 8px; color: var(--ink-2); max-width: 1000px; }
.what-this-shows b, .what-to-do b, .col-defs b { color: var(--ink); font-weight: 600; }
a.term { color: inherit; text-decoration: underline dotted; text-underline-offset: 2px; }
a.term:hover { color: var(--focus); }
.col-defs, .shown-of-total, .unk-notes { margin: 6px 0 0; color: var(--ink-2); font-size: 12px; max-width: 1100px; }
.unk-notes ol { margin: 2px 0 0; padding-left: 20px; }
.unk { color: var(--muted); white-space: nowrap; }
sup.fn { font-size: 9.5px; margin-left: 1px; }
.rid { font: 11px var(--mono); color: var(--muted); font-weight: 400; }
.finding dd p { margin: 0 0 3px; }
tbody th[scope="row"] { white-space: normal; }
td .dir, th .dir { color: var(--muted); font-weight: 400; }
#glossary dl { display: grid; grid-template-columns: minmax(150px, max-content) 1fr; gap: 5px 16px; margin: 10px 0 0; }
#glossary dt { font-weight: 600; scroll-margin-top: 56px; }
#glossary dd { margin: 0; color: var(--ink-2); max-width: 900px; }
#glossary dt:target, #glossary dt:target + dd { background: var(--warn-bg); }
#glossary details > summary { font-size: 13.5px; color: var(--ink); font-weight: 600; margin-top: 0; }
.chart { margin: 10px 0 12px; }
.chart figcaption { color: var(--ink-2); font-size: 12.5px; margin-bottom: 4px; max-width: 1000px; }
.chart svg { display: block; width: 100%; max-width: 900px; height: auto; }
.chart text { fill: var(--ink-2); font: 11px var(--sans); }
.chart text.v { fill: var(--ink); font-variant-numeric: tabular-nums; }
.chart text.at { fill: var(--muted); }
.chart text.in { fill: #fff; stroke: rgba(0,0,0,.5); stroke-width: 2.5px; paint-order: stroke; font-weight: 600; }
.chart .ax { stroke: var(--axis); }
.chart .gl { stroke: var(--grid); }
.chart .b1 { fill: var(--k-other); opacity: .6; }
.chart .b2 { fill: var(--path); }
.chart .band { fill: var(--warn); opacity: .18; }
.chart .hl { stroke: var(--ink); stroke-width: 1; opacity: .45; }
.chart .legend { margin-top: 6px; }
.legend i.hatch.on { background-image: repeating-linear-gradient(135deg, var(--ink) 0 1px, transparent 1px 4px); }
#modulegraph .mg-arrow { fill: var(--axis); }
#modulegraph .mg-arrow.mg-arrow-crit { fill: var(--path); }
#modulegraph text.mg-chain-label { fill: var(--path); font: 600 11.5px var(--sans); }
#compare .cmp-tag { position: absolute; top: -2px; font-size: 10.5px; line-height: 14px; color: var(--ink-2); white-space: nowrap; }
#trend .trend-svg text.trend-minmax { fill: var(--ink-2); }
/* v0.6 verify and fix plan */
.verify-run { font: 12px var(--mono); }
.verify-run[data-ok="false"] { color: var(--bad); }
.verify-run[data-settle="true"] { opacity: .45; }
.chart .fail { fill: none; stroke: var(--bad); }
@media (max-width: 640px) {
  #index .bar { gap: 10px; padding: 0 10px; }
  main { padding: 4px 8px 32px; }
  section { padding: 12px; }
  .filter { width: 100%; }
}
@media print {
  #index, .tools, .more, #drawer, #tip, button.tog, .no-print { display: none !important; }
  body, section { background: #fff; color: #000; }
  section { border: 0; break-inside: auto; }
  canvas { display: none; }
  .print-img { display: block; }
  details > *:not(summary) { display: block; }
}
@media (prefers-reduced-motion: reduce) { * { scroll-behavior: auto !important; } }
</style>
</head>
<body>
<pre id="js-errors" role="alert" hidden></pre>
<nav id="index" aria-label="Report sections"><div class="bar"><b>xcblame</b><ol id="index-links"></ol></div></nav>
<main>
<section id="start-here" class="start" aria-labelledby="h-start">
  <div class="head"><h2 id="h-start">Start here</h2></div>
  <p class="what-this-shows"><b>What this shows:</b> the short version of this page: what was measured, the number that matters most, and what to do first. Dotted-underlined words are explained in the <a href="#glossary">glossary</a> at the end.</p>
  <div id="start-body"><p class="na">Loading the report data.</p></div>
</section>
<section id="summary" aria-labelledby="h-summary">
  <div class="title"><h1 id="h-summary">{{TITLE}}</h1><span id="sum-badges"></span></div>
  <p class="what-this-shows" id="sum-what"><b>What this shows:</b> what xcblame read and the headline numbers. Each tile name is a link to its definition; a value that is unknown says why next to it.</p>
  <div id="sum-body"><p class="na">Loading the report data.</p></div>
</section>
<section id="timeline" aria-labelledby="h-timeline">
  <div class="head"><h2 id="h-timeline">Critical path</h2><span class="count" id="tl-count"></span>
    <div class="tools">
      <label id="tl-all-label"><input type="checkbox" id="tl-all"> All tasks</label>
      <button type="button" id="tl-in" aria-label="Zoom in">+</button>
      <button type="button" id="tl-out" aria-label="Zoom out">−</button>
      <button type="button" id="tl-reset">Reset</button>
    </div>
  </div>
  <p class="what-this-shows"><b>What this shows:</b> the <a class="term" href="#g-critical-path">critical path</a>: the chain of tasks that ran one after another from the start of the build to its end. Each row is a target; each bar is one step of the chain, labelled with its seconds. The strip at the bottom shows how many tasks ran at once (<a class="term" href="#g-utilization">utilization</a>).</p>
  <p class="what-to-do"><b>What to do:</b> only a shorter critical path makes this build finish sooner, so start with the longest bars. Shaded gaps are <a class="term" href="#g-idle-gap">idle</a>: nothing was running, which is wasted time (often a script or one target that everything waits for).</p>
  <div id="tl-body"></div>
</section>
<section id="targets" aria-labelledby="h-targets">
  <div class="head"><h2 id="h-targets">Targets</h2><span class="count"></span>
    <div class="tools"><input type="search" class="filter" placeholder="Filter targets (/)" aria-label="Filter targets"></div></div>
  <p class="what-this-shows"><b>What this shows:</b> time per <a class="term" href="#g-target">target</a>. <a class="term" href="#g-task-time">Task time</a> is all the work of the target's tasks added up; <a class="term" href="#g-on-path">on path</a> is the part that delayed the end of the build.</p>
  <p class="what-to-do"><b>What to do:</b> targets with many on-path seconds are worth speeding up or splitting. A target with a lot of task time but 0 s on path ran in parallel with other work and costs little wall time. <b>Path saving if free</b> (<a class="term" href="#g-what-if">what-if</a>) is how much shorter the critical path could get if the target took no time at all: the most that work on it can save. Rows marked "Xcode's own work" are not targets of your project. Select a row to see its tasks.</p>
  <div class="body"></div>
</section>
<section id="files" aria-labelledby="h-files">
  <div class="head"><h2 id="h-files">Files</h2><span class="count"></span>
    <div class="tools"><input type="search" class="filter" placeholder="Filter files (/)" aria-label="Filter files"></div></div>
  <p class="what-this-shows"><b>What this shows:</b> compile time per source file, slowest first: the file name, then its folder in grey. Compile seconds are work, not waiting: files compile in parallel, so only files marked "on path" made you wait. A <a class="term" href="#g-batch">batch</a> row is several files compiled by one job (its <a class="term" href="#g-members">members</a>); an <a class="term" href="#g-estimated">estimated</a> row is a file's share of its batch, not a measurement.</p>
  <p class="what-to-do"><b>What to do:</b> look at the slowest files that are on the path first: long type inference (see hotspots) or very large files are the usual cause. Files of downloaded packages are not yours to change.</p>
  <div class="body"></div>
</section>
<section id="hotspots" aria-labelledby="h-hotspots">
  <div class="head"><h2 id="h-hotspots">Type-check hotspots</h2><span class="count"></span>
    <div class="tools"><input type="search" class="filter" placeholder="Filter hotspots (/)" aria-label="Filter hotspots"></div></div>
  <p class="what-this-shows"><b>What this shows:</b> functions and expressions that took long to <a class="term" href="#g-type-check">type-check</a>, grouped by file. Only type-checking is timed here, not code generation.</p>
  <p class="what-to-do"><b>What to do:</b> add explicit types to the slow expressions or split them into smaller ones. Copy gives <code>file:line:col</code> for Xcode's Open Quickly (⇧⌘O).</p>
  <div class="body"></div>
</section>
<section id="findings" aria-labelledby="h-findings">
  <div class="head"><h2 id="h-findings">Findings and fix plan</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> problems xcblame found in build settings, the project or this Mac, in the order to fix them. Each card says what is wrong, why it costs time, how much, how sure xcblame is, what to change, and whether it is safe to try.</p>
  <p class="what-to-do"><b>What to do:</b> follow the fix plan: actions first, then <a class="term" href="#g-housekeeping">housekeeping</a>. <code>xcblame verify</code> measures a change before you keep it, and every change xcblame writes can be undone.</p>
  <div class="body"></div>
</section>
<!-- xcblame:why:start -->
<section id="why" aria-labelledby="h-why" hidden>
  <div class="head"><h2 id="h-why">Incremental why</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> why an <a class="term" href="#g-incremental">incremental build</a> re-ran work. Every task that ran gets exactly one <a class="term" href="#g-cause-class">cause</a>, so the causes add up to the executed time.</p>
  <p class="what-to-do"><b>What to do:</b> fix the biggest cause first. If the <a class="term" href="#g-unknown-share">unknown</a> share is large, run the command in the unknown row to get Xcode's own reasons.</p>
  <div id="why-body"><p class="na">Loading the incremental causes.</p></div>
</section>
<!-- xcblame:why:end -->
<!-- xcblame:fixedcosts:start -->
<section id="fixedcosts" aria-labelledby="h-fixedcosts" hidden>
  <div class="head"><h2 id="h-fixedcosts">Fixed costs</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> <a class="term" href="#g-fixed-cost">fixed costs</a>: work that runs on (nearly) every build, even when you changed nothing.</p>
  <p class="what-to-do"><b>What to do:</b> these seconds are the floor of every build, not a saving by themselves. Large script phases, signing or validation here are worth a look.</p>
  <div id="fc-body"><p class="na">Loading the fixed costs.</p></div>
</section>
<!-- xcblame:fixedcosts:end -->
<!-- xcblame:modulegraph:start -->
<section id="modulegraph" aria-labelledby="h-modulegraph" hidden>
  <div class="head"><h2 id="h-modulegraph">Module graph</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> which targets depend on which (the <a class="term" href="#g-module-graph">module graph</a>). Each arrow points from a target to a target it depends on; a target can only build after its dependencies.</p>
  <p class="what-to-do"><b>What to do:</b> the highlighted <a class="term" href="#g-longest-chain">longest chain</a> limits how short a clean build can get. Removing a dependency on that chain, or moving code off it, lets more targets build in parallel.</p>
  <div id="mg-body"><p class="na">Loading the module graph.</p></div>
</section>
<!-- xcblame:modulegraph:end -->
<section id="environment" aria-labelledby="h-environment">
  <div class="head"><h2 id="h-environment">Data quality and environment</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> how far you can trust the numbers above. Each <a class="term" href="#g-validation">check</a> tests one property of the data. Below: the Mac that ran xcblame and where the input came from.</p>
  <p class="what-to-do"><b>What to do:</b> nothing if every check passed. A failed check withholds the number it protects (that number says "unavailable because …"); a warning means a related number may be slightly off.</p>
  <div class="body"></div>
</section>
<!-- xcblame:compare:start -->
<section id="compare" aria-labelledby="h-compare" hidden>
  <div class="head"><h2 id="h-compare">Compare</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> two builds side by side: build a (the reference) and build b (the build under test). Environment differences come first because they explain most changes.</p>
  <p class="what-to-do"><b>What to do:</b> read the verdict, then the environment table. A different Xcode or Mac makes the comparison unfair; with fewer than 3 runs per side the verdict is only <a class="term" href="#g-indicative">indicative</a>.</p>
  <div id="cmp-body"><p class="na">Loading the compare data.</p></div>
</section>
<!-- xcblame:compare:end -->
<!-- xcblame:trend:start -->
<section id="trend" aria-labelledby="h-trend" hidden>
  <div class="head"><h2 id="h-trend">Trend</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> how long builds took over time, from the <a class="term" href="#g-history-entry">history</a> xcblame records after each build: one small chart per build kind, and every point in a table under it.</p>
  <p class="what-to-do"><b>What to do:</b> a line that goes up means builds are getting slower. Dotted vertical markers show where the Xcode version changed; compare builds made with the same Xcode.</p>
  <div id="trend-body"><p class="na">Loading the trend.</p></div>
</section>
<!-- xcblame:trend:end -->
<!-- xcblame:verify:start -->
<section id="verify" aria-labelledby="h-verify" hidden>
  <div class="head"><h2 id="h-verify">Verify</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> each change measured A/B: <a class="term" href="#g-arm">arm</a> A builds without it, arm B with it, several times each, through the <a class="term" href="#g-mechanism">mechanism</a> the fix will use. One mark per build.</p>
  <p class="what-to-do"><b>What to do:</b> write the kept changes with <code>xcblame fix --apply</code>; reverted changes are never written. Nothing else in the project changed: verify restores the overlay after every build.</p>
  <div id="verify-body"><p class="na">Loading the verify results.</p></div>
</section>
<section id="fixplan" aria-labelledby="h-fixplan" hidden>
  <div class="head"><h2 id="h-fixplan">Fix plan</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> the changes xcblame plans, in order, how each reaches the build and what <a class="term" href="#g-verify">verify</a> decided. Planning writes nothing to the project.</p>
  <p class="what-to-do"><b>What to do:</b> run the commands at the end, in order: verify measures each change, <code>xcblame fix --apply</code> writes only the kept ones, <code>xcblame fix --revert</code> undoes them.</p>
  <div id="fixplan-body"><p class="na">Loading the fix plan.</p></div>
</section>
<!-- xcblame:verify:end -->
<section id="glossary" aria-labelledby="h-glossary">
  <div class="head"><h2 id="h-glossary">Glossary</h2><span class="count"></span></div>
  <p class="what-this-shows"><b>What this shows:</b> every term this page uses, in plain words. Dotted-underlined words anywhere on the page link here.</p>
  <details id="glossary-list"><summary id="glossary-sum">Glossary</summary><dl id="glossary-dl"></dl></details>
</section>
</main>
<footer>Generated {{GENERATED_AT}} by xcblame {{TOOL_VERSION}}. This page loads nothing from the network.</footer>
<aside id="drawer" role="dialog" aria-modal="false" aria-labelledby="drawer-title" hidden>
  <div class="dhead"><h2 id="drawer-title" tabindex="-1"></h2><span class="count" id="drawer-count"></span><button type="button" id="drawer-close">Close</button></div>
  <div class="dbody" id="drawer-body"></div>
</aside>
<div id="tip" role="tooltip" hidden></div>
<script type="application/json" id="xcblame-data" data-encoding="json">{{DATA}}</script>
<script>
(function () {
'use strict';
var errBox = document.getElementById('js-errors');
function reportError(text) { errBox.hidden = false; errBox.textContent += text + '\n'; }
window.onerror = function (msg, src, line, col) { reportError(String(msg) + ' (line ' + line + ':' + col + ')'); };
window.addEventListener('unhandledrejection', function (e) { reportError('unhandled rejection: ' + String(e.reason)); });

// ---------- helpers (every data string goes in as text, never markup) ----------
function $(sel, root) { return (root || document).querySelector(sel); }
function el(tag, attrs) {
  var node = document.createElement(tag);
  if (attrs) for (var key in attrs) {
    var v = attrs[key];
    if (v == null || v === false) continue;
    if (key === 'class') node.className = v;
    else if (key === 'text') node.textContent = v;
    else if (key.slice(0, 2) === 'on') node.addEventListener(key.slice(2), v);
    else node.setAttribute(key, v === true ? '' : String(v));
  }
  for (var i = 2; i < arguments.length; i++) {
    var kid = arguments[i];
    if (kid == null || kid === false) continue;
    if (Array.isArray(kid)) appendAll(node, kid);
    else node.append(kid);
  }
  return node;
}
function appendAll(node, list) { list.forEach(function (k) { if (Array.isArray(k)) appendAll(node, k); else if (k != null && k !== false) node.append(k); }); }
var nf = new Intl.NumberFormat('en-US');
function int(n) { return nf.format(n); }
function secs(s) {
  if (s == null) return '';
  var a = Math.abs(s);
  if (a >= 100) return s.toFixed(0) + ' s';
  if (a >= 10) return s.toFixed(1) + ' s';
  if (a >= 1) return s.toFixed(2) + ' s';
  return (s * 1000).toFixed(0) + ' ms';
}
function msText(v) { return v >= 1000 ? (v / 1000).toFixed(2) + ' s' : v.toFixed(v < 10 ? 1 : 0) + ' ms'; }
function pct(x) { return (x * 100).toFixed(1) + '%'; }
function bytes(n) { return n >= 1073741824 ? (n / 1073741824).toFixed(0) + ' GB' : n >= 1048576 ? (n / 1048576).toFixed(0) + ' MB' : int(n) + ' B'; }
function noteAbout(arrays, word) {
  var all = [];
  arrays.forEach(function (a) { if (a) all = all.concat(a); });
  if (!word) return all[0] || null;
  var w = word.toLowerCase();
  for (var i = 0; i < all.length; i++) if (all[i].toLowerCase().indexOf(w) >= 0) return all[i];
  return null;
}
function failedCheck(id) { return (D.validation.checks || []).filter(c => c.id === id && c.status === 'fail')[0]; }
/** "unavailable because …" for a number a failed check withheld, else "unknown (reason)". */
function unknown(reason, check) {
  var f = check && failedCheck(check);
  if (f) return 'unavailable because ' + f.id + ' failed' + (f.detail ? ': ' + f.detail : '');
  return 'unknown (' + (reason || 'not measured') + ')';
}
function naLine(note) { return el('p', { class: 'na', text: 'not applicable: ' + (note || 'no data for this section') }); }
function withheldLine(note) { return el('p', { class: 'na', text: 'unavailable because ' + (note || 'the rows were withheld') }); }
function shown(n, total, share, measure) {
  return 'shown ' + int(n) + ' of ' + int(total) + (share != null ? ' (' + pct(share) + ' of ' + measure + ')' : '');
}
function setCounts(id, total, shownRows) {
  var s = document.getElementById(id);
  s.setAttribute('data-total', String(total));
  s.setAttribute('data-shown', String(shownRows));
}
function cssVar(name) { return getComputedStyle(document.documentElement).getPropertyValue(name).trim(); }
function copyText(text, button) {
  function done(ok) { if (button) { var old = button.textContent; button.textContent = ok ? 'Copied' : 'Select and copy'; setTimeout(function () { button.textContent = old; }, 1200); } }
  function fallback() {
    var area = el('textarea', { class: 'no-print' }); area.value = text; document.body.append(area); area.select();
    var ok = false; try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
    area.remove(); done(ok);
  }
  if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(function () { done(true); }, fallback);
  else fallback();
}

// ---------- generic sortable, paged table with roving tabindex ----------
// Declared before the schemaVersion dispatch below: the compare and trend views use it too (PAGE and `tables` must exist
// when they render). `cls` is a class string or a function of the row; `onShown(n)` runs after each draw; `rowAttrs(r)`
// adds attributes to a row.
var PAGE = 200;
var tables = [];
function makeTable(o) {
  var top = o.top || PAGE;
  var state = { sort: o.sort == null ? -1 : o.sort, dir: o.dir || 'descending', filter: '', limit: PAGE, open: {}, expanded: false };
  var thead = el('thead'), tbody = el('tbody'), tfoot = o.footer ? el('tfoot') : null;
  var table = el('table', null, o.caption ? el('caption', { text: o.caption }) : null, thead, tbody, tfoot);
