        { label: 'tasks b', num: true, tip: 'number of tasks on b', sort: r => r.tasks ? r.tasks.b : null, cell: r => r.tasks && r.tasks.b != null ? int(r.tasks.b) : '' },
        { label: 'status', tip: 'changed (by 100 ms or more), about the same, added (only in b) or removed (only in a)', sort: r => r.status, cell: function (r) {
