    var node = el('div', { id: 'cmp-timeline', class: 'cmp-block', 'data-axis-seconds': String(axis) }, el('h3', null, 'Timelines', el('small', { text: 'both on one axis of ' + secs(axis) })),
      what('Every task of a and of b on the same time axis (seconds since the build started); each row is a lane of tasks running one after another.'),
      legendList([['--path', 'task on the critical path'], ['--k-other', 'other task']]));
    var draws = [];
