    var rowH = lanes > 80 ? 2 : lanes > 40 ? 3 : lanes > 20 ? 4 : 6, top = 2, h = top + lanes * rowH + 18;
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
