    parts.push(el('div', { class: 'banner', role: 'status' }, el('strong', { text: 'This comparison is truncated to fit its size cap.' }),
      ' The file has a size cap (8 MB by default, --max-report-bytes) so it opens fast. Totals and headline numbers still cover every row; to stay under the cap these lists were shortened, in this order:',
      el('ol', null, steps.map(function (s) { return el('li', { text: s.step + ': kept ' + int(s.kept) + ' of ' + int(s.total) + (s.shownShare != null ? ' (' + pct(s.shownShare) + ' of the measure)' : '') }); })),
      'Every row: ', code('xcblame compare <a> <b> --format json --top all')));
  }
  if ((doc.notes || []).length) {
    parts.push(el('h3', { text: 'Notes from xcblame (' + doc.notes.length + ')' }),
