// ---------- trend view (xcblame.trend/1; DOM contract in docs/SCHEMA-v0.4.md "HTML views") ----------
// xcblame:trend:js:start
// Lane C: fills #trend-body from the trend document `doc`: one group per `--by` value, one SVG small multiple per build
// kind (wall line, p50 and p95 rules, Xcode-change markers, one mark per history entry) plus a table of the same points.
// Every data string goes in as text; the page loads nothing.
function renderTrend(doc) {
  var body = $('#trend-body');
  var NS = 'http://www.w3.org/2000/svg';
  var by = doc.filter && doc.filter.by ? doc.filter.by : null;
  function svg(tag, attrs) {
