    if (attrs) for (var key in attrs) { if (attrs[key] != null) node.setAttribute(key, String(attrs[key])); }
    for (var i = 2; i < arguments.length; i++) { if (arguments[i] != null) node.append(arguments[i]); }
    return node;
  }
  function fmtTime(t) { return localTime(t); }
  function fmtDay(t) { var x = localTime(t); return /^\d{4}-/.test(x) ? x.slice(0, 10) : ''; }
  function machineText(m) { var p = String(m || '').split('/'); return p.length === 3 ? p[0] + ', ' + p[1].replace(/c$/, ' cores') + ', ' + p[2].replace(/g$/, ' GB') : (m || ''); }
  var gitWhy = 'none (see the note below)';
  function shortCommit(c) { return c ? String(c).slice(0, 8) : null; }
  function slug(text) { return String(text).replace(/[^A-Za-z0-9_-]/g, '-'); }
  function groupLabel(key) {
    if (key == null) return 'All builds';
    if (key === 'unknown') return 'No ' + by + ' recorded';
    return by === 'commit' ? shortCommit(key) : key;
  }
  function pointText(p) {
    return [p.id, fmtTime(p.time), p.wall == null ? 'wall unknown' : 'wall ' + secs(p.wall), p.xcode ? 'Xcode ' + p.xcode : null,
      p.commit ? 'commit ' + shortCommit(p.commit) : null].filter(Boolean).join(' · ');
  }

  var f = doc.filter || {};
  var parts = [];
  if (f.kind) parts.push('kind ' + f.kind);
  if (f.scheme) parts.push('scheme ' + f.scheme);
  if (f.since) parts.push('since ' + fmtTime(f.since));
  if (by) parts.push('grouped by ' + by);
  var filter = el('p', { id: 'trend-filter', class: 'muted', text: (parts.length ? 'Filter: ' + parts.join(', ') + '. ' : 'No filter. ')
    + int(doc.entriesUsed || 0) + ' of ' + int(doc.entriesTotal || 0) + ' history entries used.' });

  function stat(cls, label, value) {
    return el('span', { class: cls, 'data-value': value == null ? null : value, text: label + ' ' + (value == null ? 'n/a' : secs(value)) });
  }

  function chart(series, readout) {
    var pts = series.points, W = 480, H = 146, L = 44, R = 34, T = 22, B = 30;
    var pw = W - L - R, ph = H - T - B;
    var walls = pts.map(p => p.wall).filter(v => v != null);
    // The axis spans the data (and the p50 and p95 rules) with a margin, so a small change stays visible; it starts
    // at 0 only when the data is close to it.
    var vals = walls.concat([series.wall.p50, series.wall.p95].filter(v => v != null));
    var lo = vals.length ? Math.min.apply(null, vals) : 0, hi = vals.length ? Math.max.apply(null, vals) : 1;
    var pad = (hi - lo) * 0.12 || hi * 0.1 || 1;
    lo = Math.max(0, lo - pad); hi += pad;
    function x(i) { return L + (pts.length < 2 ? pw / 2 : pw * i / (pts.length - 1)); }
    function y(v) { return T + ph * (1 - (v - lo) / (hi - lo)); }
    var floor = T + ph;
    var root = svg('svg', { class: 'trend-svg', viewBox: '0 0 ' + W + ' ' + H, role: 'img',
      'aria-label': series.kind + ' wall time over ' + pts.length + ' builds' });
    root.append(svg('line', { class: 'trend-base', x1: L, x2: L + pw, y1: floor, y2: floor }),
      svg('line', { class: 'trend-base', x1: L, x2: L, y1: T, y2: floor }),
      svg('text', { x: L - 4, y: floor + 3, 'text-anchor': 'end' }, document.createTextNode(secs(lo))),
      svg('text', { x: L - 4, y: T + 3, 'text-anchor': 'end' }, document.createTextNode(secs(hi))),
      svg('text', { x: 2, y: 9 }, document.createTextNode('wall time')),
      svg('text', { x: L + pw / 2, y: H - 2, 'text-anchor': 'middle' }, document.createTextNode('builds, oldest → newest')));
    // Fastest and slowest builds, labelled with their seconds.
    var minI = -1, maxI = -1;
    pts.forEach(function (p, i) { if (p.wall == null) return; if (minI < 0 || p.wall < pts[minI].wall) minI = i; if (maxI < 0 || p.wall > pts[maxI].wall) maxI = i; });
    if (minI >= 0 && walls.length > 1) {
      [[maxI, 'max '], [minI, 'min ']].forEach(function (m) {
        var mx = Math.min(L + pw - 24, Math.max(L + 24, x(m[0]))), py = y(pts[m[0]].wall);
        // Below the point near the top of the plot, above it near the bottom.
        var ty = py - T < 14 ? py + 13 : py - 6;
        root.append(svg('text', { class: 'trend-minmax', x: mx, y: Math.min(floor - 3, ty), 'text-anchor': 'middle' }, document.createTextNode(m[1] + secs(pts[m[0]].wall))));
      });
    }
