      labelY = Math.max(ry + 3, labelY + 10);
      root.append(svg('text', { class: 'trend-rule-label ' + r[0], x: L + pw + 4, y: labelY }, document.createTextNode(r[0])));
    });
    var line = pts.map((p, i) => p.wall == null ? null : x(i).toFixed(1) + ',' + y(p.wall).toFixed(1))
      .filter(Boolean).join(' ');
    if (walls.length > 1) root.append(svg('polyline', { class: 'trend-line', points: line }));
    var index = {};
    pts.forEach(function (p, i) { index[p.id] = i; });
    (series.xcodeChangeMarkers || []).forEach(function (m, mi) {
      var at = index[m.atId];
      if (at == null || at < 1) return;
