      role: n.collapsed ? null : 'button', 'aria-label': tip, transform: 'translate(' + p.x + ' ' + p.y + ')' },
      svgEl('title', null, document.createTextNode(tip)),
      svgEl('rect', { width: NW, height: NH, rx: 5 }),
      svgEl('text', { x: 8, y: 14 }, document.createTextNode(clipName(n.name))),
      svgEl('text', { class: 'mg-sub', x: 8, y: 27 }, document.createTextNode((n.owner || '') + (n.taskTime != null ? ' · ' + secs(n.taskTime) : ''))));
