              text: pass + ' pass · ' + warn + ' warn' + (fail ? ' · ' + fail + ' fail' : '') }),
    ' ',
    D.degraded ? el('a', { href: '#environment', class: 'badge bad', title: GL['data-quality'][2], text: 'data quality: reduced' }) : null,
    ' ',
    el('span', { class: 'badge', title: D.redacted ? GL.redacted[2] : 'user names and paths are shown as they are', text: D.redacted ? 'redacted' : 'not redacted' })];
  $('#sum-badges').replaceChildren.apply($('#sum-badges'), badges.filter(Boolean));
  var parts = [];
  parts.push(el('code', { class: 'input-path', text: D.input.path || unknown('no input path recorded') }));
  var facts = el('ul', { class: 'facts' });
  facts.append(el('li', null, 'Xcode ', el('strong', { text: x.value || 'unknown' }), ' ',
    x.source ? el('span', { class: 'badge', title: 'how xcblame knows: ' + (x.evidence || []).join('; '), text: x.source === 'inferred' ? 'inferred from the log' : x.source }) : null,
    x.value ? null : el('span', { class: 'muted', text: ' (' + (noteAbout([x.notes], 'value') || 'no evidence') + ')' })));
  var ds = D.diagnosticsSummary;
  facts.append(el('li', null, el('strong', { text: int(ds.errors) }), ' errors, ', el('strong', { text: int(ds.warnings) }), ' warnings',
    el('span', { class: 'muted', text: ' (' + int(ds.unique) + ' unique of ' + int(ds.occurrences) + ')' })));
  if (env) {
    var cores = env.performanceCores != null ? (env.performanceCores + (env.efficiencyCores || 0)) + ' cores (' + env.performanceCores + ' performance + ' + (env.efficiencyCores || 0) + ' efficiency)' : env.logicalCPUCount != null ? env.logicalCPUCount + ' cores' : 'cores unknown';
    facts.append(el('li', null, 'Analyzed on this Mac: ', el('strong', { text: env.hwModel || 'unknown model' }), ', ' + cores +
      (env.memoryBytes != null ? ', ' + bytes(env.memoryBytes) : '') + (env.macOSProductVersion ? ', macOS ' + env.macOSProductVersion : '')));
  } else facts.append(el('li', { class: 'muted', text: 'Machine not captured (--no-env)' }));
  if (D.project) facts.append(el('li', null, 'Project ', el('strong', { text: D.project.container.split('/').pop() }),
    ' (' + (D.project.settingsSource || 'no effective settings') + ')'));
  parts.push(facts);
  function tile(label, id, value, sub, check, member, notes, plain) {
    var text = value != null, why = text ? null : plain || unknown(noteAbout(notes || [b.notes, D.notes], member), check);
    return el('div', null, el('dt', null, term(id, label)),
      el('dd', { class: text ? null : 'text', title: why, text: text ? value : why }),
      sub ? el('small', { text: sub }) : null);
  }
  var tiles = el('dl', { class: 'tiles' },
    tile('Log span', 'log-span', b.span != null ? secs(b.span) : null, b.idle != null ? 'first to last task; idle ' + secs(b.idle) : 'first to last task', 'V1', 'span'),
    tile('Process wall', 'process-wall', T.processWall != null ? secs(T.processWall) : null,
         T.outsideLogSeconds != null ? secs(T.outsideLogSeconds) + ' outside the log' : null, null, 'processWall', [T.notes],
         noteAbout([T.notes], 'processWall') ? 'not measured (only xcblame build measures it)' : null),
    tile('Busy', 'busy', b.busy != null ? secs(b.busy) : null, 'at least one task running', 'V1', 'busy'),
    tile('Task time', 'task-time', b.taskTime != null ? secs(b.taskTime) : null, int(b.tasks) + ' tasks added up (they overlap)', 'V1', 'taskTime'),
    tile('CPU', 'cpu', m.cpuSeconds != null ? secs(m.cpuSeconds) : null, 'from the ' + int(m.tasksWithCPU) + ' of ' + int(b.tasks) + ' tasks that report CPU', 'V1', 'cpu', [m.notes]),
