// ---------- 3. targets ----------
var targetsApi = null;
function renderTargets() {
  if (DOCTOR) return noBuildSection('targets', D.targetsTotal);
  var sec = 'targets', body = $('#targets .body'), rows = D.targets;
  setCounts(sec, D.targetsTotal, rows ? rows.length : 0);
  if (!rows) {
    hideFilter(sec);
    body.replaceChildren(D.targetsTotal > 0 ? withheldLine(noteAbout([D.notes], 'targets')) : naLine(noteAbout([D.notes], 'targets')));
    return;
  }
  $('#targets .count').textContent = shown(rows.length, D.targetsTotal, D.targetsShownShare, 'task time');
  var fn = footnotes(), unknownCell = fn.ref;
  var cpWhy = CP ? 'this target has no on-path value' : 'the critical path was not computed: ' + (noteAbout([T.notes, D.graph.notes, D.notes], 'critical path') || 'no timing to build it from');
  var OWNER_WORDS = { app: 'your app', localPackage: 'local package', remotePackage: 'downloaded package', systemModules: 'Xcode\'s own work (system modules)', buildSystem: 'Xcode\'s own work (planning)' };
  targetsApi = makeTable({
    notes: fn,
    caption: 'Select a row to list its tasks and highlight it in the timeline.',
    rows: rows, sort: 2, text: r => r.name + ' ' + (r.owner || '') + ' ' + (r.project || ''),
    pin: r => r.isOther,
    rowClass: r => r.isOther ? 'other' : '',
    open: function (r) { location.hash = 'target=' + encodeURIComponent(r.name); },
    columns: [
      { label: 'Target', head: true, tip: 'the Xcode or package target, with its project or package in grey', sort: r => r.name.toLowerCase(), cell: function (r) {
        return el('span', null, r.name, r.project ? el('span', { class: 'muted', text: '  ' + r.project.split('/').pop() }) : null); } },
      { label: 'Owner', tip: 'where the target comes from: your app, a local package, a downloaded package, or Xcode\'s own work', sort: r => r.owner, cell: r => r.owner ? (OWNER_WORDS[r.owner] || r.owner) : (r.isOther ? '' : unknownCell('owner not classified: the target is not in the project or package graph xcblame read', 'not classified')) },
      { label: 'Task time', num: true, tip: 'seconds of all its tasks added up, and its share of the build\'s task time', sort: r => r.taskTime, cell: function (r) {
        return el('span', null, secs(r.taskTime), r.share != null ? el('span', { class: 'muted', text: ' ' + pct(r.share) }) : null); } },
      { label: 'On path', num: true, tip: 'seconds of this target on the critical path: the part that delayed the end of the build', sort: r => r.onPathSeconds, cell: r => r.onPathSeconds != null ? secs(r.onPathSeconds) : unknownCell(cpWhy, 'no path') },
      { label: 'Path saving if free', num: true, tip: 'what-if: how much shorter the critical path could get if this target took no time (from the build plan only)', sort: r => r.whatIfSeconds, cell: function (r) {
        return r.whatIfSeconds != null ? el('span', { title: 'critical path up to this much shorter if the target took no time (build plan only)', text: secs(r.whatIfSeconds) })
          : r.isOther || r.name === '(unattributed)' ? unknownCell('this row collects tasks without a target, so there is nothing to remove from the path', 'n/a (no target)')
          : unknownCell(CP && CP.basis !== 'dag' ? 'the path saving needs Xcode\'s build plan: this path was found from ' + (BASIS_WORDS[CP.basis] || CP.basis) + '; pass --build-description to xcblame analyze, or use xcblame build' : cpWhy, 'not computed'); } },
      { label: 'Tasks', num: true, tip: 'number of tasks of this target', sort: r => r.tasks, cell: r => int(r.tasks) },
      { label: 'Kind mix', tip: 'task time split by task kind; hover the bar for the percentages, the biggest kind is written next to it', cell: function (r) {
