        var total = r.taskTime || 1, bar = el('span', { class: 'mix' }), label = [];
        var merged = {}; r.kinds.forEach(function (k) { var v = kindColorVar(k.key); merged[v] = (merged[v] || 0) + k.taskTime; });
        r.kinds.forEach(function (k) { label.push(k.key + ' ' + pct(k.taskTime / total)); });
        Object.keys(merged).forEach(function (v) { var w = merged[v] / total; if (w > 0) bar.append(el('span', { style: 'flex: ' + w.toFixed(4) + ' 1 0; background: var(' + v + ')' })); });
        bar.setAttribute('role', 'img'); bar.setAttribute('aria-label', label.join(', ')); bar.title = label.join('\n');
        var top = r.kinds.filter(k => !k.isOther).sort((a, b) => b.taskTime - a.taskTime)[0];
        return el('span', { style: 'display: flex; gap: 6px; align-items: center' }, bar, top ? el('small', { class: 'muted', text: top.key + ' ' + pct(top.taskTime / total) }) : null); } },
      { label: 'Busy', num: true, tip: 'seconds in which at least one task of this target was running', sort: r => r.busy, cell: r => r.busy != null ? secs(r.busy) : unknownCell('busy time not computed for this row', 'not computed') }
    ]
  });
