  var chart = barChart({ id: 'chart-targets', total: D.targetsTotal, fmt: secs, axis: 'seconds',
    caption: ['Targets by ', term('on-path', 'on-path'), ' seconds (blue inner bar) against their ', term('task-time', 'task time'), ' (grey outer bar). Look for long blue bars: they delayed the build.'],
    legend: [['--k-other', 'task time (all its tasks added up)'], ['--path', 'on the critical path']],
    note: tops.length < rows.filter(r => !r.isOther).length ? 'Top ' + tops.length + ' of ' + rows.filter(r => !r.isOther).length + ' targets by on-path seconds; the table lists every row.' : null,
    rows: tops.map(r => ({ label: r.name, v: r.taskTime, v2: r.onPathSeconds || 0, text: secs(r.taskTime) + ' total · ' + (r.onPathSeconds != null ? secs(r.onPathSeconds) + ' on path' : 'on path unknown') })) });
  body.replaceChildren(chart || el('span'), rows.some(r => r.kinds) ? kindLegend() : el('span'), targetsApi.node,
    shownLine(rows.length, D.targetsTotal, D.targetsShownShare, 'task time', fullCmd()));
}

// ---------- drawer: one target's tasks ----------
var lastFocus = null;
function openTarget(name) {
  var drawer = $('#drawer'), row = (D.targets || []).filter(r => r.name === name)[0];
  lastFocus = document.activeElement;
  $('#drawer-title').textContent = name;
