    },
    columns: [
      { label: 'Line:col', tip: 'where the declaration starts in the file', cell: function (h) { return el('code', { text: h.line + ':' + h.col }); } },
      { label: 'Declaration', head: true, cls: 'path', tip: 'the function, property or expression', cell: h => h.declaration },
      { label: 'Kind', tip: 'functionBody: a whole function; expression: one expression', cell: h => h.kind },
      { label: 'Time', num: true, tip: 'type-check milliseconds; ×N when the compiler checked it N times (for example once per architecture)', cell: h => msText(h.ms) + (h.occurrences > 1 ? ' ×' + h.occurrences : '') },
      { label: 'Source', tip: 'which compiler output reported it', cell: function (h) { return el('span', { class: 'badge', text: h.source }); } },
